class Cache:
    def __init__(self, clock):
        self.clock = clock
        self.store = {}

    def put(self, key, value, ttl):
        self.store[key] = {"value": value, "insertion_time": self.clock(), "ttl": ttl}

    def get(self, key, default=None):
        entry = self.store.get(key)
        if entry is None:
            return default
        if self.clock() >= entry["insertion_time"] + entry["ttl"]:
            del self.store[key]
            return default
        return entry["value"]

